97:/// Matches receiver-first StarRocks dispatch with later same-node sender results.
98:#[derive(Debug, Default)]
99:pub(crate) struct LocalExchange {
100:    inner: Mutex<ExchangeState>,
101:}
102:
103:impl LocalExchange {
104:    /// Registers a receiver fragment, returning it when every exchange input is complete.
105:    pub(crate) fn register_receiver(
106:        &self,
107:        fragment_instance_id: FragmentInstanceId,
108:        expected_senders: Vec<(i32, usize)>,
109:        params: TExecPlanFragmentParams,
110:    ) -> Result<Option<ReadyFragment>, String> {
111:        if expected_senders.is_empty() {
112:            return Err("receiver fragment has no exchange inputs".to_string());
113:        }
114:        let mut expected_by_node = HashMap::with_capacity(expected_senders.len());
115:        for (node_id, expected) in expected_senders {
116:            if expected == 0 {
117:                return Err(format!("exchange node {node_id} expects no senders"));
118:            }
119:            if expected_by_node.insert(node_id, expected).is_some() {
120:                return Err(format!(
121:                    "duplicate exchange node {node_id} in receiver fragment"
122:                ));
123:            }
124:        }
125:        let mut state = self.lock();
126:        if state.receivers.contains_key(&fragment_instance_id) {
127:            return Err(format!(
128:                "duplicate receiver registration for fragment {fragment_instance_id}"
129:            ));
130:        }
131:        state.receivers.insert(
132:            fragment_instance_id,
133:            PendingReceiver {
134:                params,
135:                expected_senders: expected_by_node,
136:            },
137:        );
138:        Self::take_ready(&mut state, fragment_instance_id)
139:    }
140:
141:    /// Records one sender as produced, returning the receiver when this completes its sender set.
142:    pub(crate) fn push_sender(
143:        &self,
144:        key: ExchangeKey,
145:        sender_id: i32,
146:        source: SenderSource,
147:    ) -> Result<Option<ReadyFragment>, String> {
148:        let mut state = self.lock();
149:        let senders = state.sources.entry(key).or_default();
150:        if senders.contains_key(&sender_id) {
151:            return Err(format!("duplicate sender {sender_id} for exchange {key:?}"));
152:        }
153:        senders.insert(sender_id, source);
154:        Self::take_ready(&mut state, key.fragment_instance_id)
155:    }
156:
157:    /// Records one `transmit_packed` frame from a remote sender: a staged batch, eos, or both.
158:    /// Returns the receiver when the eos completes its sender set.
159:    pub(crate) fn push_remote_frame(
160:        &self,
161:        key: ExchangeKey,
162:        sender_id: i32,
163:        seq: i64,
164:        eos: bool,
165:        names: Vec<String>,
166:        batch: Option<StagedBatch>,
167:    ) -> Result<Option<ReadyFragment>, String> {
168:        if names.is_empty() {
169:            return Err(format!(
170:                "remote sender {sender_id} for exchange {key:?} sent a frame without column \
171:                 names; the receiver cannot bind its input stream schema"
172:            ));
173:        }
174:        if batch.is_none() && !eos {
175:            return Err(format!(
176:                "remote sender {sender_id} for exchange {key:?} sent frame seq {seq} carrying \
177:                 neither a batch nor eos"
178:            ));
179:        }
180:        let mut state = self.lock();
181:
182:        let expected_seq = state.remote_seq.entry((key, sender_id)).or_insert(0);
183:        if seq < *expected_seq {
184:            // brpc reconnect-retry can replay a frame the peer already processed; its batch (if
185:            // any) landed in the same lease the first delivery recorded, so dropping the replay
186:            // loses nothing and leaks nothing.
187:            info!(
188:                exchange = ?key,
189:                sender_id, seq, "dropping duplicate remote exchange frame"
190:            );
191:            return Ok(None);
192:        }
193:        if seq > *expected_seq {
194:            return Err(format!(
195:                "remote sender {sender_id} for exchange {key:?} skipped from frame seq \
196:                 {expected_seq} to {seq}; a frame was lost"
197:            ));
198:        }
199:        *expected_seq += 1;
200:
201:        let senders = state.sources.entry(key).or_default();
202:        let source = senders
203:            .entry(sender_id)
204:            .or_insert_with(|| SenderSource::Remote {
205:                names: names.clone(),
206:                sender_id,
207:                batches: Vec::new(),
208:                closed: false,
209:            });
210:        let SenderSource::Remote {
211:            names: known_names,
212:            batches,
213:            closed,
214:            ..
215:        } = source
216:        else {
217:            return Err(format!(
218:                "remote frame for exchange {key:?} sender {sender_id} collides with a local \
219:                 parked sender of the same id"
220:            ));
221:        };
222:        if *closed {
223:            return Err(format!(
224:                "remote sender {sender_id} for exchange {key:?} sent frame seq {seq} after eos"
225:            ));
226:        }
227:        if known_names != &names {
228:            return Err(format!(
229:                "remote sender {sender_id} for exchange {key:?} changed its column names from \
230:                 {known_names:?} to {names:?}"
231:            ));
232:        }
233:        if let Some(batch) = batch {
234:            if batch.metadata.is_empty() {
235:                return Err(format!(
236:                    "remote sender {sender_id} for exchange {key:?} sent frame seq {seq} with \
237:                     empty pack metadata"
238:                ));
239:            }
240:            batches.push(batch);
241:        }
242:        if eos {
243:            *closed = true;
244:        }
245:        Self::take_ready(&mut state, key.fragment_instance_id)
246:    }
247:
248:    fn take_ready(
249:        state: &mut ExchangeState,
250:        fragment_instance_id: FragmentInstanceId,
251:    ) -> Result<Option<ReadyFragment>, String> {
252:        let Some(receiver) = state.receivers.get(&fragment_instance_id) else {
253:            return Ok(None);
254:        };
255:        for (&node_id, &expected) in &receiver.expected_senders {
256:            let key = ExchangeKey {
257:                fragment_instance_id,
258:                node_id,
259:            };
260:            let sources = state.sources.get(&key);
261:            let total = sources.map(HashMap::len).unwrap_or(0);
262:            if total > expected {
263:                return Err(format!(
264:                    "exchange {key:?} received {total} senders but expected {expected}"
265:                ));
266:            }
267:            // A remote sender counts only once its eos arrived; a local parked one is done by
268:            // construction.
269:            let complete = sources
270:                .map(|senders| {
271:                    senders
272:                        .values()
273:                        .filter(|source| source.is_complete())
274:                        .count()
275:                })
276:                .unwrap_or(0);
277:            if complete != expected {
278:                return Ok(None);
279:            }
280:        }
281:
282:        let receiver = state
283:            .receivers
284:            .remove(&fragment_instance_id)
285:            .expect("receiver checked above");
286:        let mut node_ids = receiver.expected_senders.into_keys().collect::<Vec<_>>();
287:        node_ids.sort_unstable();
288:        let inputs = node_ids
289:            .into_iter()
290:            .map(|node_id| {
291:                let key = ExchangeKey {
292:                    fragment_instance_id,
293:                    node_id,
294:                };
295:                let mut senders = state.sources.remove(&key).unwrap_or_default();
296:                let mut sender_ids = senders.keys().copied().collect::<Vec<_>>();
297:                sender_ids.sort_unstable();
298:                let sources = sender_ids
299:                    .into_iter()
300:                    .map(|sender_id| senders.remove(&sender_id).expect("sender id came from map"))
301:                    .collect();
302:                ReadyExchangeInput { node_id, sources }
303:            })
304:            .collect();
305:        // The receiver is leaving the rendezvous; drop its remote-sender sequence tracking too.
306:        state
307:            .remote_seq
308:            .retain(|(key, _), _| key.fragment_instance_id != fragment_instance_id);
309:        Ok(Some(ReadyFragment {
310:            params: receiver.params,
311:            inputs,
312:        }))
313:    }
314:
315:    fn lock(&self) -> std::sync::MutexGuard<'_, ExchangeState> {
316:        self.inner
317:            .lock()
318:            .unwrap_or_else(|poisoned| poisoned.into_inner())
319:    }
320:}
