117:/// GPU-backed [`FragmentExecutor`] running plans on an embedded Sirius engine.
118:///
119:/// The engine context lives on a dedicated thread; this handle forwards plans to it and waits for
120:/// the result. Dropping it closes the request channel, which ends the thread and tears the context
121:/// down (joined for an ordered teardown).
122:#[derive(Debug)]
123:pub struct SiriusEngine {
124:    /// Sender to the engine thread. `Mutex<Option<..>>` makes the `!Sync` sender shareable and
125:    /// lets `Drop` close the channel before joining; sends are brief (the thread serializes work).
126:    requests: Mutex<Option<Sender<EngineRequest>>>,
127:    /// Engine thread handle, taken and joined on drop.
128:    thread: Mutex<Option<JoinHandle<()>>>,
129:    /// Thread-safe staging-arena handle (`None` when `SIRIUS_EXCHANGE_STAGING_BYTES` is unset),
130:    /// serving every `staging_*` call directly on the caller's thread.
131:    ///
132:    /// INVARIANT: staging leases must never funnel through `requests` — a fragment wedged
133:    /// inside `run()` would starve every peer's `request_staging_lease` and stall their
134:    /// cross-CN exchanges. Off-thread service is safe because lease/release/base/capacity only
135:    /// take the arena's internal mutex and make no CUDA calls; the engine thread keeps its own
136:    /// direct arena access (`Context::staging_release` for remote-input leases, and
137:    /// `export_packed` leasing internally) — one shared C++ allocator, two entry points.
138:    staging: Option<sirius::StagingArena>,
139:}
140:
141:impl SiriusEngine {
142:    /// Brings up the engine on a dedicated thread (fail-fast) and returns a handle.
143:    ///
144:    /// Blocks until the context is initialized — or bring-up fails — so a bad config or GPU
145:    /// failure surfaces here, before any RPC is served. `settings` carries the resolved Sirius
146:    /// YAML path (built-in defaults when `None`), the engine artifact directory, and the CUDA
147:    /// device pin.
148:    pub fn start(settings: EngineSettings) -> Result<Self, String> {
149:        Self::configure_duckdb_extensions()?;
150:        Self::configure_engine_environment(&settings)?;
151:        let (request_tx, request_rx) = channel::<EngineRequest>();
152:        // Readiness carries the staging-arena handle out of the engine thread: the context
153:        // itself never leaves that thread, but the handle is `Send + Sync` by design so
154:        // staging calls can bypass the request channel (see the module doc).
155:        let (ready_tx, ready_rx) = channel::<Result<Option<sirius::StagingArena>, String>>();
156:        let thread = std::thread::Builder::new()
157:            .name("sirius-engine".to_string())
158:            .spawn(move || engine_thread(settings.config, request_rx, ready_tx))
159:            .map_err(|err| format!("failed to spawn sirius-engine thread: {err}"))?;
160:        match ready_rx.recv() {
161:            Ok(Ok(staging)) => Ok(Self {
162:                requests: Mutex::new(Some(request_tx)),
163:                thread: Mutex::new(Some(thread)),
164:                staging,
165:            }),
166:            Ok(Err(err)) => Err(err),
167:            Err(_) => Err("sirius-engine thread exited during bring-up".to_string()),
168:        }
169:    }
170:
171:    /// Points the embedded DuckDB context at the locally built extensions used by Substrait.
172:    fn configure_duckdb_extensions() -> Result<(), String> {
173:        let build_dir = std::env::var_os("SIRIUS_BUILD_DIR")
174:            .map(PathBuf::from)
175:            .unwrap_or_else(|| {
176:                PathBuf::from(env!("CARGO_MANIFEST_DIR"))
177:                    .join("../..")
178:                    .join("build/release")
179:            });
180:        let extensions = [
181:            (
182:                "SIRIUS_DUCKDB_PARQUET_EXTENSION",
183:                build_dir.join("extension/parquet/parquet.duckdb_extension"),
184:            ),
185:            (
186:                "SIRIUS_DUCKDB_CORE_FUNCTIONS_EXTENSION",
187:                build_dir.join("extension/core_functions/core_functions.duckdb_extension"),
188:            ),
189:        ];
190:        for (variable, path) in extensions {
191:            if std::env::var_os(variable).is_some() {
192:                continue;
193:            }
194:            if !path.is_file() {
195:                return Err(format!(
196:                    "DuckDB extension for {variable} is missing at {}",
197:                    path.display()
198:                ));
199:            }
200:            // SAFETY: this runs before the engine thread and RPC servers start, so no concurrent
201:            // code reads or writes these process environment variables.
202:            unsafe { std::env::set_var(variable, &path) };
203:        }
204:        Ok(())
205:    }
206:
207:    /// Points the engine's log directory at `<engine_dir>/log` and pins the CUDA device when
208:    /// requested. Environment already set by the operator wins (matching the extension-path
209:    /// precedent above), but an ignored `--gpu-device` is called out rather than dropped silently.
210:    fn configure_engine_environment(settings: &EngineSettings) -> Result<(), String> {
211:        if std::env::var_os("SIRIUS_LOG_DIR").is_none() {
212:            let log_dir = settings.engine_dir.join("log");
213:            std::fs::create_dir_all(&log_dir).map_err(|err| {
214:                format!(
215:                    "failed to create engine log directory {}: {err}",
216:                    log_dir.display()
217:                )
218:            })?;
219:            // SAFETY: this runs before the engine thread and RPC servers start, so no concurrent
220:            // code reads or writes these process environment variables.
221:            unsafe { std::env::set_var("SIRIUS_LOG_DIR", &log_dir) };
222:        }
223:        if let Some(device) = settings.gpu_device {
224:            if let Some(existing) = std::env::var_os("CUDA_VISIBLE_DEVICES") {
225:                warn!(
226:                    existing = %existing.to_string_lossy(),
227:                    requested = device,
228:                    "CUDA_VISIBLE_DEVICES is already set; ignoring --gpu-device"
229:                );
230:            } else {
231:                // SAFETY: same pre-thread-spawn window as above; nothing else touches the
232:                // environment yet.
233:                unsafe { std::env::set_var("CUDA_VISIBLE_DEVICES", device.to_string()) };
234:            }
235:        }
236:        Ok(())
237:    }
238:}
