240:/// Engine-thread body: bring up the context, signal readiness, then serve requests until the
241:/// request channel closes. The context is dropped here, on this thread, when the loop ends.
242:fn engine_thread(
243:    config: Option<PathBuf>,
244:    requests: Receiver<EngineRequest>,
245:    ready: Sender<Result<Option<sirius::StagingArena>, String>>,
246:) {
247:    let context = match build_context(config) {
248:        Ok(context) => {
249:            // A send error means the caller is already gone; nothing to serve. The staging
250:            // handle crosses to the caller so leases are served off this thread.
251:            if ready.send(Ok(context.staging_arena())).is_err() {
252:                return;
253:            }
254:            context
255:        }
256:        Err(err) => {
257:            let _ = ready.send(Err(err));
258:            return;
259:        }
260:    };
261:
262:    // Sender fragments whose output is parked on the GPU, waiting for their receivers to be
263:    // dispatched. Parked ONCE per fragment; `parked_slots` maps each destination's SenderSlot to
264:    // (park id, its output stream). Declared after `context` so the fragments drop *first*: a
265:    // fragment borrows the engine it runs on, and the borrow checker enforces the order the C++
266:    // side depends on.
267:    let mut parked: HashMap<u64, ParkedOutput<'_>> = HashMap::new();
268:    let mut parked_slots: HashMap<SenderSlot, (u64, u64)> = HashMap::new();
269:    let mut next_park_id: u64 = 0;
270:    // Why a slot's parked output went away, for the slots the blanket wipe below destroys.
271:    // Without this the wipe is silent and the NEXT export of an unrelated slot reports
272:    // "no parked sender output", which is collateral -- it masks the error that actually killed
273:    // the query. MEASURED: TPC-H q08 reported that error for weeks while the real failure was an
274:    // OOM in HASH_JOIN. Bounded: an entry is dropped as soon as the slot is parked again.
275:    let mut poisoned: HashMap<SenderSlot, String> = HashMap::new();
276:
277:    info!("sirius-engine thread ready");
278:    // One request at a time until the handle (and its sender) is dropped. Every respond-send
279:    // error is ignored: the waiting caller may have been dropped/cancelled.
280:    while let Ok(request) = requests.recv() {
281:        match request {
282:            EngineRequest::Run(request) => {
283:                let result = run_fragment(
284:                    &context,
285:                    &mut parked,
286:                    &mut parked_slots,
287:                    &poisoned,
288:                    &mut next_park_id,
289:                    &request,
290:                );
291:                if let Err(err) = &result {
292:                    // A failed query leaves its parked senders unreachable — the receiver that
293:                    // would have consumed them is the thing that just failed. Dropping them
294:                    // releases the GPU memory their batches hold rather than leaking it for the
295:                    // process's lifetime.
296:                    //
297:                    // The wipe is process-wide, so it also destroys OTHER in-flight fragments'
298:                    // parked output. Record why, and say so out loud: a drain that fails right
299:                    // after this used to report only "no parked sender output", which names the
300:                    // victim and hides the culprit.
301:                    if !parked_slots.is_empty() {
302:                        warn!(
303:                            slots = parked_slots.len(),
304:                            error = %err,
305:                            "discarding every parked sender output on this CN after a fragment failure"
306:                        );
307:                    }
308:                    // Replace, never accumulate: only the most recent wipe can explain a slot
309:                    // that is missing now, and this bounds the map by the live slot count.
310:                    poisoned.clear();
311:                    for slot in parked_slots.keys() {
312:                        poisoned.insert(slot.clone(), err.clone());
313:                    }
314:                    parked.clear();
315:                    parked_slots.clear();
316:                }
317:                let _ = request.respond.send(result);
318:            }
319:            #[cfg(test)]
320:            EngineRequest::Sleep(duration) => std::thread::sleep(duration),
321:            EngineRequest::ExportNext { slot, respond } => {
322:                let result = export_next(&mut parked, &parked_slots, &poisoned, slot);
323:                let _ = respond.send(result);
324:            }
325:            EngineRequest::DropParked { slot, respond } => {
326:                let result = release_slot(&mut parked, &mut parked_slots, &poisoned, &slot);
327:                let _ = respond.send(result);
328:            }
329:            EngineRequest::PinTable { spec, respond } => {
330:                info!(name = %spec.name, tier = spec.tier.as_str(), "pin_table starting");
331:                let started = std::time::Instant::now();
332:                let engine_spec = sirius::PinTableSpec {
333:                    path: spec.path.clone(),
334:                    tier: spec.tier.as_str().to_string(),
335:                    name: spec.name.clone(),
336:                    cols: spec.cols.clone(),
337:                    format: spec.format.clone(),
338:                    schema: spec.schema.clone(),
339:                };
340:                let result = context
341:                    .pin_table(&engine_spec)
342:                    .map_err(|err| format!("pin_table '{}' failed: {err}", spec.name));
343:                info!(
344:                    name = %spec.name,
345:                    elapsed_ms = started.elapsed().as_millis() as u64,
346:                    ok = result.is_ok(),
347:                    "pin_table finished"
348:                );
349:                let _ = respond.send(result);
350:            }
351:            EngineRequest::UnpinTable { name, respond } => {
352:                let result = context
353:                    .unpin_table(&name)
354:                    .map_err(|err| format!("unpin_table '{name}' failed: {err}"));
355:                let _ = respond.send(result);
356:            }
357:        }
358:    }
359:    // Fragments must be gone before the context they borrow.
360:    drop(parked_slots);
361:    drop(parked);
362:    info!("sirius-engine thread shutting down");
363:}
