379:/// Packs the next batch parked under `slot` into a fresh staging lease.
380:fn export_next(
381:    parked: &mut HashMap<u64, ParkedOutput<'_>>,
382:    parked_slots: &HashMap<SenderSlot, (u64, u64)>,
383:    poisoned: &HashMap<SenderSlot, String>,
384:    slot: SenderSlot,
385:) -> Result<Option<StagedBatch>, String> {
386:    let (park_id, stream) = parked_slots
387:        .get(&slot)
388:        .copied()
389:        .ok_or_else(|| missing_slot(poisoned, &slot, "export"))?;
390:    let entry = parked
391:        .get_mut(&park_id)
392:        .ok_or_else(|| format!("parked fragment vanished under {slot:?}"))?;
393:    let batch = entry
394:        .fragment
395:        .export_packed(stream)

395:        .export_packed(stream)
396:        .map_err(|err| format!("failed to export a packed batch for {slot:?}: {err}"))?;
397:    Ok(batch.map(|batch| StagedBatch {
398:        metadata: batch.metadata,
399:        offset: batch.offset,
400:        len: batch.len,
401:        rows: Some(batch.rows),
402:    }))
403:}
