405:/// Releases one destination's claim on a parked fragment; the fragment (and the GPU memory its
406:/// remaining batches hold) drops when the LAST destination releases. Exactly-once per slot: a
407:/// second release of the same slot is a loud error, never a silent double-drop.
408:fn release_slot(
409:    parked: &mut HashMap<u64, ParkedOutput<'_>>,
410:    parked_slots: &mut HashMap<SenderSlot, (u64, u64)>,
411:    poisoned: &HashMap<SenderSlot, String>,
412:    slot: &SenderSlot,
413:) -> Result<(), String> {
414:    let (park_id, _) = parked_slots
415:        .remove(slot)
416:        .ok_or_else(|| missing_slot(poisoned, slot, "drop"))?;
417:    let entry = parked
418:        .get_mut(&park_id)
419:        .ok_or_else(|| format!("parked fragment vanished under {slot:?}"))?;
420:    entry.outstanding -= 1;
421:    if entry.outstanding == 0 {
422:        parked.remove(&park_id);
423:    }
424:    Ok(())
425:}
