776:impl FragmentExecutor for SiriusEngine {
777:    fn run(&self, run: FragmentRun<'_>) -> Result<Option<FragmentResult>, String> {
778:        self.engine_call(|respond| {
779:            EngineRequest::Run(ExecuteRequest {
780:                plan: run.plan.to_substrait_bytes(),
781:                stream_inputs: run.plan.stream_inputs.clone(),
782:                inputs: run.inputs,
783:                remote_inputs: run.remote_inputs,
784:                outputs: run.outputs,
785:                broadcast: run.broadcast,
786:                hash_keys: run.hash_keys,
787:                label: run.label,
788:                respond,
789:            })
790:        })
791:    }
792:
793:    // The three staging calls below run on the CALLER's thread, never the engine thread: a
794:    // peer's lease request must succeed even while the engine is deep inside a fragment run.
795:

795:
796:    fn staging_info(&self) -> Result<(u64, u64), String> {
797:        let arena = self.staging_arena()?;
798:        Ok((arena.base() as u64, arena.capacity()))
799:    }
800:
801:    fn staging_lease(&self, len: u64) -> Result<u64, String> {
802:        self.staging_arena()?
803:            .lease(len)
804:            .map_err(|err| format!("staging lease of {len} bytes failed: {err}"))
805:    }
806:
807:    fn staging_release(&self, offset: u64) -> Result<(), String> {
808:        self.staging_arena()?
809:            .release(offset)
810:            .map_err(|err| format!("staging release of offset {offset} failed: {err}"))
811:    }
812:
813:    fn export_packed_next(&self, slot: SenderSlot) -> Result<Option<StagedBatch>, String> {
814:        self.engine_call(|respond| EngineRequest::ExportNext { slot, respond })
815:    }
816:
817:    fn drop_parked(&self, slot: SenderSlot) -> Result<(), String> {
818:        self.engine_call(|respond| EngineRequest::DropParked { slot, respond })
819:    }
820:
821:    fn pin_table(&self, spec: &PinTableSpec) -> Result<String, String> {
822:        let spec = spec.clone();
823:        self.engine_call(|respond| EngineRequest::PinTable { spec, respond })
824:    }
825:
826:    fn unpin_table(&self, name: &str) -> Result<String, String> {
827:        let name = name.to_string();
828:        self.engine_call(|respond| EngineRequest::UnpinTable { name, respond })
829:    }
830:}
