1111:    /// End-to-end: drive a `local_files` parquet plan through the engine actor and read the rows
1112:    /// back. Exercises the dedicated-thread bring-up, the channel round-trip, and GPU execution.
1113:    /// Requires a GPU and `LD_LIBRARY_PATH` to the built engine (like the `sirius` crate's context
1114:    /// test); the parquet extension path is set from `SIRIUS_BUILD_DIR` (default mirrors sirius-sys).
1115:    /// Points the embedded DuckDB at the locally-built parquet extension so it can bind
1116:    /// `parquet_scan`. Call under [`crate::GPU_ENGINE_TEST_LOCK`] so no other context bring-up
1117:    /// reads the environment concurrently.
1118:    fn ensure_parquet_extension_env() {
1119:        if std::env::var_os("SIRIUS_DUCKDB_PARQUET_EXTENSION").is_none() {
1120:            let manifest = env!("CARGO_MANIFEST_DIR");
1121:            let build_dir = std::env::var("SIRIUS_BUILD_DIR")
1122:                .unwrap_or_else(|_| format!("{manifest}/../../build/release"));
1123:            let parquet = format!("{build_dir}/extension/parquet/parquet.duckdb_extension");
1124:            // SAFETY: the GPU lock is held, so no other thread touches the environment here.
1125:            unsafe { std::env::set_var("SIRIUS_DUCKDB_PARQUET_EXTENSION", parquet) };
1126:        }
1127:    }
