1129:    /// Writes the tiny `(id BIGINT, name VARCHAR)` parquet fixture at `path`:
1130:    /// rows (1, "a"), (2, "b"), (3, "c").
1131:    fn write_users_parquet(path: &std::path::Path) {
1132:        let schema = Arc::new(Schema::new(vec![
1133:            Field::new("id", DataType::Int64, false),
1134:            Field::new("name", DataType::Utf8, false),
1135:        ]));
1136:        let ids: ArrayRef = Arc::new(Int64Array::from(vec![1, 2, 3]));
1137:        let names: ArrayRef = Arc::new(StringArray::from(vec!["a", "b", "c"]));
1138:        let batch = RecordBatch::try_new(schema.clone(), vec![ids, names]).unwrap();
1139:        let file = std::fs::File::create(path).unwrap();
1140:        let mut writer = ArrowWriter::try_new(file, schema, None).unwrap();
1141:        writer.write(&batch).unwrap();
1142:        writer.close().unwrap();
1143:    }
