1145:    /// The engine-actor mirror of the sirius crate's `packed_hop_matches_relay_hop`: a sender
1146:    /// parks its output, `export_packed_next` drains it into staging leases, and a receiver run
1147:    /// with `remote_inputs` delivers exactly the fixture rows — proving the staging info/lease/
1148:    /// release handle path, the ExportNext/DropParked plumbing, and the push-then-release
1149:    /// contract, GPU-side, without any network. Requires a GPU and
1150:    /// `SIRIUS_EXCHANGE_STAGING_BYTES` support.
1151:    #[test]
1152:    fn engine_pushes_staged_remote_batches() {
1153:        let _guard = crate::GPU_ENGINE_TEST_LOCK
1154:            .lock()
