807:    /// Executes an `ADMIN EXECUTE` script: parse, then run each command on the fragment
808:    /// executor in order, stopping at the first failure. Returns one summary line per command
809:    /// ('\n'-joined — the FE renders each line as a result row).
810:    fn handle_execute_command(
811:        &self,
812:        request: &ExecuteCommandRequestPb,
813:    ) -> std::result::Result<String, String> {
814:        // The FE hardcodes this command name for ADMIN EXECUTE (ExecuteScriptExecutor.java);
815:        // reject anything else by name rather than guessing at its payload.
816:        match request.command.as_deref() {
817:            Some("execute_script") => {}
818:            other => {
819:                return Err(format!(
820:                    "unsupported execute_command command {other:?}; this CN only accepts \
821:                     'execute_script' (ADMIN EXECUTE ON <node_id> '<script>')"
822:                ));
823:            }
824:        }
825:        let script = request
826:            .params
827:            .as_deref()
828:            .filter(|params| !params.trim().is_empty())
829:            .ok_or_else(|| {
830:                "empty script; supported commands: pin_table path=<file-or-glob> \
831:                 tier=gpu|host name=<name> [cols=c1,c2,...] [format=parquet|duckdb] \
832:                 [schema=<schema>] | unpin_table <name>"
833:                    .to_string()
834:            })?;
835:        // Bound parse/log cost; the grammar never needs scripts anywhere near this size.
836:        const MAX_SCRIPT_BYTES: usize = 64 * 1024;
837:        if script.len() > MAX_SCRIPT_BYTES {
838:            return Err(format!(
839:                "script is {} bytes; the CN caps admin scripts at {MAX_SCRIPT_BYTES}",
840:                script.len()
841:            ));
842:        }
843:        tracing::info!(script, "execute_command admin script accepted");
844:        let commands = crate::admin_command::parse_script(script)?;
845:        let total = commands.len();
846:        let mut lines = Vec::with_capacity(total);
847:        for (index, command) in commands.into_iter().enumerate() {
848:            let line = match &command {
849:                crate::admin_command::AdminCommand::PinTable(spec) => self.executor.pin_table(spec),
850:                crate::admin_command::AdminCommand::UnpinTable { name } => {
851:                    self.executor.unpin_table(name)
852:                }
853:            }
854:            .map_err(|err| format!("command {} of {total}: {err}", index + 1))?;
855:            lines.push(line);
856:        }
857:        let outcome = lines.join("\n");
858:        tracing::info!(outcome, "execute_command admin script finished");
859:        Ok(outcome)
860:    }
