862:    /// Runs one dispatched receiver, parking a failure where `fetch_data` can see it. Returns
863:    /// the next receiver when this fragment's own sink completed another sender set.
864:    fn run_ready_fragment(&self, ready: ReadyFragment) -> Vec<ReadyFragment> {
865:        let id = Self::fragment_instance_id(&ready.params);
866:        let query_id = Self::query_id(&ready.params);
867:        let is_result_fragment = matches!(Self::is_mysql_result_sink(&ready.params), Ok(true));
868:        // `join_into_ready` keeps this fragment's own remote drains inside this call, so a drain
869:        // failure is attributed to the same query as any other failure of this fragment.
870:        match self
871:            .execute_ready_fragment(ready)
872:            .and_then(FragmentOutcome::join_into_ready)
873:        {
874:            Ok(next) => next,
875:            Err(error) => {
876:                match (id, query_id) {
877:                    (Some(id), Some(query_id)) => {
878:                        if is_result_fragment {
879:                            // The FE polls fetch_data on this id; its reserved entry becomes
880:                            // the error instead of waiting forever.
881:                            tracing::error!(fragment_instance_id = %id, error = %error, "dispatched result fragment failed");
882:                        } else {
883:                            // An intermediate receiver has no FE-polled entry of its own, so
884:                            // its failure must reach the query's result-fragment instances —
885:                            // otherwise the FE polls until its timeout and the stalled
886:                            // fetch_data wedges this CN's whole frame loop.
887:                            tracing::error!(
888:                                fragment_instance_id = %id,
889:                                error = %error,
890:                                "dispatched intermediate receiver fragment failed; failing the query's result fragments"
891:                            );
892:                        }
893:                        // Fails this id, every reserved result instance of the query, and
894:                        // records the failure so a result fragment arriving later fails on
895:                        // registration instead of waiting on senders that never deliver.
896:                        self.results.fail_query(query_id, id, error);
897:                    }
898:                    (Some(id), None) => {
899:                        // Defensive: exec params carry both ids or neither, so this arm should
900:                        // be unreachable. Park the error under the instance id at least.
901:                        tracing::error!(fragment_instance_id = %id, error = %error, "dispatched receiver fragment without a query_id failed");
902:                        self.results.fail(id, error);
903:                    }
904:                    (None, _) => {
905:                        tracing::error!(error = %error, "dispatched receiver fragment without a fragment_instance_id failed");
906:                    }
907:                }
908:                Vec::new()
909:            }
910:        }
911:    }
