953:    /// Restores descriptor tables omitted by StarRocks's per-query descriptor cache protocol.
954:    fn resolve_descriptor_table(
955:        &self,
956:        params: &TExecPlanFragmentParams,
957:    ) -> std::result::Result<TExecPlanFragmentParams, String> {
958:        let mut resolved = params.clone();
959:        let Some(query_id) = params
960:            .params
961:            .as_ref()
962:            .map(|exec| FragmentInstanceId::from(&exec.query_id))
963:        else {
964:            return Ok(resolved);
965:        };
966:        let Some(desc) = params.desc_tbl.as_ref() else {
967:            return Ok(resolved);
968:        };
969:        let is_cached_reference = desc.is_cached == Some(true)
970:            && desc.slot_descriptors.as_ref().is_none_or(Vec::is_empty)
971:            && desc.tuple_descriptors.is_empty()
972:            && desc.table_descriptors.as_ref().is_none_or(Vec::is_empty);
973:        let mut cache = self
974:            .descriptor_tables
975:            .lock()
976:            .unwrap_or_else(|poisoned| poisoned.into_inner());
977:        if is_cached_reference {
978:            resolved.desc_tbl = Some(
979:                cache
980:                    .get(&query_id)
981:                    .cloned()
982:                    .ok_or_else(|| format!("descriptor table cache miss for query {query_id}"))?,
983:            );
984:        } else {
985:            cache.insert(query_id, desc.clone());
986:        }
987:        Ok(resolved)
988:    }
