990:    /// Writes the received fragment params to `$SIRIUS_CN_DUMP_FRAGMENTS/fragment-<seq>.txt`
991:    /// (debug format) for offline plan analysis. No-op when the variable is unset.
992:    fn dump_fragment(params: &TExecPlanFragmentParams) -> Option<u64> {
993:        use std::sync::atomic::{AtomicU64, Ordering};
994:        let Ok(dir) = std::env::var("SIRIUS_CN_DUMP_FRAGMENTS") else {
995:            return None;
996:        };
997:        static SEQ: AtomicU64 = AtomicU64::new(0);
998:        let seq = SEQ.fetch_add(1, Ordering::Relaxed);
999:        let path = std::path::Path::new(&dir).join(format!("fragment-{seq:04}.txt"));
1000:        if let Err(err) = std::fs::write(&path, format!("{params:#?}")) {
1001:            tracing::warn!(error = %err, path = %path.display(), "failed to dump fragment params");
1002:        }
1003:        Some(seq)
1004:    }
