1308:    /// Staging arena `(base, capacity)`, cached after the first successful engine round-trip.
1309:    fn staging_info(&self) -> std::result::Result<(u64, u64), String> {
1310:        let mut cached = self
1311:            .staging_info
1312:            .lock()
1313:            .unwrap_or_else(|poisoned| poisoned.into_inner());
1314:        if let Some(info) = *cached {
1315:            return Ok(info);
1316:        }
1317:        let info = self.executor.staging_info()?;
1318:        *cached = Some(info);
1319:        Ok(info)
1320:    }
