168:/// Runs a translated fragment, either parking its output for a downstream fragment or returning
169:/// its rows.
170:///
171:/// The seam is synchronous and one fragment at a time: the engine serializes queries, and a
172:/// sender's output is parked on the GPU — as native batches, not Arrow — until its receiver is
173:/// dispatched. A sender's rows therefore never leave the device between fragments.
174:///
175:/// TODO(starrocks-execute): dispatch still blocks until a fragment completes. Concurrency needs
176:/// per-query lifecycle isolation in the engine; until then `run` is called from a blocking worker
177:/// so the BRPC runtime stays responsive.
178:pub trait FragmentExecutor: std::fmt::Debug + Send + Sync {
179:    /// Runs `run`. Returns rows only for a fragment with no `output` slot — a result fragment.
180:    fn run(&self, run: FragmentRun<'_>) -> Result<Option<FragmentResult>, String>;
181:
182:    /// Exchange staging arena `(device base address, capacity in bytes)`, for transport memory
183:    /// registration. Errors when the executor has no arena — the default for every executor
184:    /// that is not the engine with `SIRIUS_EXCHANGE_STAGING_BYTES` set.
185:    fn staging_info(&self) -> Result<(u64, u64), String> {
186:        Err("this fragment executor has no exchange staging arena \
187:             (engine build with SIRIUS_EXCHANGE_STAGING_BYTES required)"
188:            .to_string())
189:    }
190:
191:    /// Leases `len` bytes of the staging arena, returning the lease offset from the base.
192:    fn staging_lease(&self, len: u64) -> Result<u64, String> {
193:        let _ = len;
194:        Err("this fragment executor has no exchange staging arena \
195:             (engine build with SIRIUS_EXCHANGE_STAGING_BYTES required)"
196:            .to_string())
197:    }
198:
199:    /// Returns the staging lease at `offset`.
200:    fn staging_release(&self, offset: u64) -> Result<(), String> {
201:        let _ = offset;
202:        Err("this fragment executor has no exchange staging arena \
203:             (engine build with SIRIUS_EXCHANGE_STAGING_BYTES required)"
204:            .to_string())
205:    }
206:
207:    /// Packs the next batch parked under `slot` into a fresh staging lease; `Ok(None)` once the
208:    /// parked output is drained. The lease stays outstanding until
209:    /// [`staging_release`](Self::staging_release).
210:    fn export_packed_next(&self, slot: SenderSlot) -> Result<Option<StagedBatch>, String> {
211:        let _ = slot;
212:        Err("this fragment executor cannot export packed batches \
213:             (engine build with SIRIUS_EXCHANGE_STAGING_BYTES required)"
214:            .to_string())
215:    }
216:
217:    /// Drops the parked fragment under `slot`, releasing the GPU memory its batches hold. Called
218:    /// after the drained output has been transmitted (or on a failed transmit, so a wedged
219:    /// cross-node query does not pin its output for the process lifetime).
220:    fn drop_parked(&self, slot: SenderSlot) -> Result<(), String> {
221:        let _ = slot;
222:        Err("this fragment executor parks nothing to drop".to_string())
223:    }
224:
225:    /// Pins a table into the engine's scan cache (`CALL pin_table` semantics). Blocks for the
226:    /// whole materialization, serialized with fragment runs on the engine thread. Returns a
227:    /// one-line summary.
228:    fn pin_table(&self, spec: &PinTableSpec) -> Result<String, String> {
229:        let _ = spec;
230:        Err("this fragment executor does not support pin_table (engine build required)".to_string())
231:    }
232:
233:    /// Removes the pinned entry `name`, releasing its memory. Returns a one-line summary.
234:    fn unpin_table(&self, name: &str) -> Result<String, String> {
235:        let _ = name;
236:        Err(
237:            "this fragment executor does not support unpin_table (engine build required)"
238:                .to_string(),
239:        )
240:    }
241:}
