243:/// Placeholder executor that fabricates one row so the result path works without a GPU.
244:#[derive(Clone, Copy, Debug, Default)]
245:pub struct StubExecutor;
246:
247:impl FragmentExecutor for StubExecutor {
248:    fn run(&self, run: FragmentRun<'_>) -> Result<Option<FragmentResult>, String> {
249:        // A stub sender parks nothing; the rendezvous only needs it to succeed.
250:        if !run.outputs.is_empty() {
251:            return Ok(None);
252:        }
253:        self.execute(run.plan).map(Some)
254:    }
255:}
256:
257:impl StubExecutor {
258:    /// One placeholder row per output column, so the FE→client path works without a GPU.
259:    fn execute(&self, translated: &TranslatedPlan) -> Result<FragmentResult, String> {
260:        // TODO(starrocks-execute): replace with a SiriusExecutor that hands
261:        // `translated.to_substrait_bytes()` to the embedded Sirius engine, executes it on the
262:        // GPU, and imports the result via the Arrow C Data Interface. That executor will hold an
263:        // `Arc<sirius::SiriusContext>` threaded in from `main` (see `BrpcServer::with_executor`).
264:        // For now
265:        // we emit one placeholder string row per output column so the FE→client path is exercised.
266:        let names = &translated.output_names;
267:        if names.is_empty() {
268:            return Ok(FragmentResult {
269:                batches: Vec::new(),
270:            });
271:        }
272:        let fields: Vec<Field> = names
273:            .iter()
274:            .map(|name| Field::new(name, DataType::Utf8, true))
275:            .collect();
276:        let columns: Vec<ArrayRef> = names
277:            .iter()
278:            .map(|_| Arc::new(StringArray::from(vec![Some("stub")])) as ArrayRef)
279:            .collect();
280:        let batch = RecordBatch::try_new(Arc::new(Schema::new(fields)), columns)
281:            .map_err(|err| format!("failed to build stub result batch: {err}"))?;
282:        Ok(FragmentResult {
283:            batches: vec![batch],
284:        })
285:    }
286:}
