2027:    /// Polls until `predicate` holds; receiver execution now happens on the dispatch worker.
2028:    fn wait_until(what: &str, predicate: impl Fn() -> bool) {
2029:        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
2030:        while !predicate() {
2031:            assert!(
2032:                std::time::Instant::now() < deadline,
