2039:    /// Polls `fetch_data` until the dispatched receiver's rows land, panicking on an error
2040:    /// status or on EOS before any rows arrived.
2041:    fn fetch_rows_eventually(
2042:        service: &SiriusComputeNodeService,
2043:        hi: i64,
2044:        lo: i64,
2045:    ) -> prpc::Response {
2046:        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
2047:        loop {
2048:            let response = route(
2049:                service,
2050:                methods::FETCH_DATA,
2051:                fetch_request(hi, lo),
2052:                Vec::new(),
2053:            );
2054:            let result = PFetchDataResult::decode(response.body.as_slice()).unwrap();
2055:            assert_eq!(
2056:                result.status.status_code,
2057:                TStatusCode::OK.0,
2058:                "{:?}",
2059:                result.status.error_msgs
2060:            );
2061:            if !response.attachment.is_empty() {
2062:                return response;
2063:            }
2064:            assert_eq!(
2065:                result.eos,
2066:                Some(false),
2067:                "receiver reported EOS before delivering rows"
2068:            );
2069:            assert!(
2070:                std::time::Instant::now() < deadline,
2071:                "timed out waiting for receiver rows"
2072:            );
2073:            std::thread::sleep(std::time::Duration::from_millis(2));
2074:        }
2075:    }
