private boolean isInternalCancel(PPlanFragmentCancelReason cancelReason) {
    return cancelReason.equals(PPlanFragmentCancelReason.LIMIT_REACH) ||
            cancelReason.equals(PPlanFragmentCancelReason.QUERY_FINISHED);
